            throw new PoolRefusedException("The pool " + member.getName() + " is a member of a pool already");
        }
        Map<Long, Long> parentOf = new HashMap<>();
        Map<Long, List<Long>> childrenOf = new HashMap<>();
        List<Long> ids = pools.findBySheetIdOrderByIdAsc(sheetId).stream().map(Pool::getId).toList();
        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(ids)) {
            if (m.getMemberPoolId() != null) {
                parentOf.put(m.getMemberPoolId(), m.getPoolId());
                childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
            }
        }
        // The pools from the pool up to the top, the pool counted.
        int above = 0;
        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
            if (at.equals(member.getId())) {
                throw new PoolRefusedException("The pool " + pool.getName() + " would contain itself");
            }
            above++;
        }
        if (above + height(member.getId(), childrenOf) > MAX_DEPTH) {
            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep");
        }
    }

    /** The pools in the longest chain down from this pool, the pool counted. */
    private int height(Long poolId, Map<Long, List<Long>> childrenOf) {
        int below = 0;
        for (Long child : childrenOf.getOrDefault(poolId, List.of())) {
            below = Math.max(below, height(child, childrenOf));
        }
        return below + 1;
    }
}
-- A sheet's pools: each a name, on a sheet at most once, and its members. A member is a person of
-- the sheet with a share percent (more than 0.00, at most 100.00); a person is in a pool at most
-- once, and may be in several pools. A retired member's share counts as 0.00 toward the pool's
-- total, which the screen works out from the people as they are.
CREATE TABLE pool (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

CREATE TABLE pool_member (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
-- A pool member may be another pool of the sheet instead of a person: exactly one of person_id and
-- member_pool_id is set. A pool is a member of at most one pool, never of itself through any chain,
-- and a chain of pools is at most three deep. A pool that is a member of another has no pot of its
-- own: its pot is its cut in the pool above.
ALTER TABLE pool_member ALTER COLUMN person_id DROP NOT NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);

