            <input
              type="date"
              [id]="'pool-member-to-' + row.pool.id"
              data-testid="pool-member-to"
              [value]="entries()[row.pool.id]?.to ?? ''"
              (input)="setDate(row.pool.id, 'to', value($event))"
            />
            <button type="button" data-testid="pool-member-add" (click)="addMember(row.pool)">Add member</button>
            @if (memberErrors()[row.pool.id]; as message) {
              <p role="alert" data-testid="pool-error">{{ message }}</p>
            }
          </li>
        }
      </ul>
    </section>
  `,
})
export class Pools {
  /** The sheet's people, a member's name and retirement read from here. */
  readonly people = input.required<PoolPerson[]>();

  protected readonly store = inject(PoolStore);
  private readonly settings = inject(SettingStore);
  private readonly session = inject(Session);
  protected readonly name = signal('');
  protected readonly error = signal<string | null>(null);
  /** The member (the select's value), share and dates chosen on each pool's row, by pool id. */
  protected readonly entries = signal<Record<number, { member?: string; share?: string; from?: string; to?: string }>>({});
  /** The error shown on each pool's row, by pool id. */
  protected readonly memberErrors = signal<Record<number, string | null>>({});
  /** Whether a submit is waiting for its answer; a second submit meanwhile is dropped. */
  private readonly busy = signal(false);

  protected readonly rows = computed<PoolRow[]>(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    const pools = this.store.pools();
    const poolById = new Map(pools.map((p) => [p.id, p]));
    const today = this.session.today();
    const cutsByPool = poolCuts(pools, this.people(), this.settings.pot(), today);
    return pools.map((pool) => {
      const total = totalOf(sharesOf(pool, byId, today));
      const cut = cutsByPool.get(pool.id) ?? null;
      const members = pool.members.map((m, i) => {
        const member = m.memberPoolId !== null ? poolById.get(m.memberPoolId) : undefined;
        return {
          key: m.personId !== null ? `${m.personId}` : `pool-${member?.name ?? m.memberPoolId}`,
          name: m.personId !== null ? (byId.get(m.personId)?.name ?? '') : `pool:${member?.name ?? ''}`,
          share: m.share,
          cut: cut && !outOn(m, today) ? figure(cut[i]) : '',
        };
      });
      return { pool, members, total: figure(total), balanced: total === 10000n };
    });
  });

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /** Download every pool's members as CSV: pools in the order added, each pool's members in the
   *  order added, a pool member as pool:<name>, with the share and the cut as their rows show them. */
  protected exportCsv(): void {
    const rows = [
      ['pool', 'member', 'share', 'cut'],
      ...this.rows().flatMap((row) => row.members.map((m) => [row.pool.name, m.name, m.share, m.cut])),
    ];
    // A field holding a quote, comma or line break is quoted (quotes doubled); every line ends with a line feed.
    const field = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
    const text = rows.map((r) => r.map(field).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([text], { type: 'text/csv' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `pools-${this.session.sheetId() ?? 'sheet'}.csv`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
  }

  protected setMember(poolId: number, member: string): void {
    this.entries.update((e) => ({ ...e, [poolId]: { ...e[poolId], member } }));
    this.memberErrors.update((e) => ({ ...e, [poolId]: null }));
  }

  protected setShare(poolId: number, share: string): void {
    this.entries.update((e) => ({ ...e, [poolId]: { ...e[poolId], share } }));
    this.memberErrors.update((e) => ({ ...e, [poolId]: null }));
  }

  protected setDate(poolId: number, which: 'from' | 'to', date: string): void {
    this.entries.update((e) => ({ ...e, [poolId]: { ...e[poolId], [which]: date } }));
    this.memberErrors.update((e) => ({ ...e, [poolId]: null }));
  }

  /** Add the typed pool, its name trimmed; a blank name or one already a pool's is refused beside the form. */
  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy()) return;
    this.error.set(null);
    const name = this.name().trim();
    if (name === '') {
      this.error.set('Type a name for the pool.');
      return;
    }
    this.busy.set(true);
    try {
      await this.store.add(name);
    } catch {
      this.error.set(`The pool ${name} could not be added: the name may be a pool's already.`);
    } finally {
      this.busy.set(false);
    }
  }

  /** Add the chosen person or pool with the typed share and optional dates; a person already in the
   *  pool, a pool that may not be a member of it, a share not more than 0.00 and at most 100.00 with
   *  two decimals, or a to-date before the from-date, is refused on the pool's row. */
  protected async addMember(pool: Pool): Promise<void> {
    if (this.busy()) return;
    const refuse = (message: string) => this.memberErrors.update((e) => ({ ...e, [pool.id]: message }));
    this.memberErrors.update((e) => ({ ...e, [pool.id]: null }));
    const entry = this.entries()[pool.id] ?? {};
    const member = choiceOf(entry.member);
    const share = (entry.share ?? '').trim();
    const from = entry.from || null;
    const to = entry.to || null;
    if (!member) {
      refuse('Choose a person or a pool to add.');
      return;
    }
    if (!SHARE.test(share) || Number(share) <= 0 || Number(share) > 100) {
      refuse('A share is more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    if (from !== null && to !== null && to < from) {
      refuse('The to-date may not be before the from-date.');
      return;
    }
    if (member.kind === 'person' && pool.members.some((m) => m.personId === member.id)) {
      refuse('That person is in the pool already.');
      return;
    }
    this.busy.set(true);
    try {
      await this.store.addMember(pool.id, member, share, from, to);
    } catch {
      refuse(
        member.kind === 'person'
          ? 'The member could not be added: they may be in the pool already.'
          : 'The pool could not be added: a pool is a member of at most one pool, cannot contain itself, and a chain of pools is at most three deep.',
      );
    } finally {
      this.busy.set(false);
    }
  }
}
import { Component, inject, signal } from '@angular/core';
import { Figures } from '../../core/figures';
import { LOCALES, Locale, Session } from '../../core/session';
import { AuditViewer } from '../audit/audit-viewer';
import { People } from '../people/people';
import { TreeSearch } from '../search/tree-search';
import { SettingStore } from '../settings/settings';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [AuditViewer, Figures, People, TreeSearch],
  template: `
    <div appFigures>
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form (submit)="saveLocale($event)">
        <label for="user-locale">Locale</label>
        <select
          id="user-locale"
          data-testid="user-locale"
          [value]="localeInput() ?? session.locale()"
          (change)="localeInput.set(locale($event)); localeError.set(null)"
        >
          @for (l of locales; track l) {
            <option [value]="l">{{ l }}</option>
          }
        </select>
        <button type="submit" data-testid="user-locale-save">Save locale</button>
        Locale <strong data-testid="user-locale-current">{{ session.locale() }}</strong>
      </form>
      @if (localeError(); as error) {
        <p role="alert" data-testid="user-locale-error">{{ error }}</p>
      }

      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
      </form>
      @if (sheetError(); as error) {
        <p role="alert" data-testid="sheet-load-error">{{ error }}</p>
      }

      @if (session.sheetId(); as sheet) {
        <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
        <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
        <form (submit)="saveToday($event)">
          <label for="sheet-today-date">Change today</label>
          <input
            id="sheet-today-date"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <p>
          Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong>
          <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
        </p>
        <p>Parent sheet <strong data-testid="sheet-parent">{{ settings.parent() }}</strong></p>
        <form (submit)="cloneSheet($event)">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input
            id="sheet-clone-to"
            data-testid="sheet-clone-to"
            [value]="cloneInput()"
            (input)="cloneInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-clone">Clone sheet</button>
          Last clone made <strong data-testid="sheet-cloned-to">{{ clonedTo() }}</strong>
        </form>
        @if (todayError(); as error) {
          <p role="alert" data-testid="sheet-error">{{ error }}</p>
        }
        <form (submit)="setAsOf($event)">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong>
        </form>
        @if (asOfError(); as error) {
          <p role="alert" data-testid="asof-error">{{ error }}</p>
        }
        <app-people />
        <app-tree-search />
        <app-audit-viewer />
      } @else {
        <p data-testid="home-empty">No sheet loaded.</p>
      }
    } @else {
      <form (submit)="signIn($event)">
        <label for="signin-name">Name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
      </form>
      @if (signinError(); as error) {
        <p role="alert" data-testid="signin-error">{{ error }}</p>
      }
    }
    </div>
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly settings = inject(SettingStore);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayInput = signal('');
  protected readonly todayError = signal<string | null>(null);
  protected readonly asOfInput = signal('');
  protected readonly cloneInput = signal('');
  /** The id of the last clone this screen made of the active sheet. */
  protected readonly clonedTo = signal('');
  protected readonly asOfError = signal<string | null>(null);

  protected readonly locales = LOCALES;
  /** The locale chosen in the select and not yet saved; null shows the saved one. */
  protected readonly localeInput = signal<Locale | null>(null);
  protected readonly localeError = signal<string | null>(null);

  protected locale(event: Event): Locale {
    return (event.target as HTMLSelectElement).value as Locale;
  }

  protected async saveLocale(event: Event): Promise<void> {
    event.preventDefault();
    this.localeError.set(null);
    try {
      await this.session.saveLocale(this.localeInput() ?? this.session.locale());
      this.localeInput.set(null);
    } catch {
      this.localeError.set('The locale could not be saved.');
    }
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected signIn(event: Event): void {
    event.preventDefault();
    this.signinError.set(this.session.signIn(this.nameInput()) ? null : 'Type a name to sign in.');
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    this.todayError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Type a sheet id to load.');
      return;
    }
    try {
      await this.session.loadSheet(id);
      this.clonedTo.set('');
    } catch {
      this.sheetError.set('The sheet could not be loaded.');
    }
  }

  protected async archive(): Promise<void> {
    this.todayError.set(null);
    try {
      await this.session.archive();
    } catch {
      this.todayError.set('The sheet could not be archived.');
    }
  }

  protected async cloneSheet(event: Event): Promise<void> {
    event.preventDefault();
    this.todayError.set(null);
    this.clonedTo.set('');
    const to = this.cloneInput().trim();
    if (!to) {
      this.todayError.set('Type a sheet id to clone to.');
      return;
    }
    try {
      this.clonedTo.set(await this.session.cloneTo(to));
    } catch {
      this.todayError.set('The sheet could not be cloned.');
    }
  }

  /** Show the sheet as of the typed date on this screen only. */
  protected setAsOf(event: Event): void {
    event.preventDefault();
    this.asOfError.set(null);
    this.todayError.set(null);
    const date = this.asOfInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.asOfError.set('Type a date (yyyy-mm-dd) to show the sheet as of.');
      return;
    }
    this.session.setAsOf(date);
  }

  /** Show the sheet as it is now again. */
  protected clearAsOf(): void {
    this.asOfError.set(null);
    this.todayError.set(null);
    this.asOfInput.set('');
    this.session.clearAsOf();
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    this.todayError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Type a date (yyyy-mm-dd) for today.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.todayError.set('Today could not be changed.');
    }
  }
}
